export type Post = {
  id: number;
  title: string;
  content: string;
};

// In-memory store (replace with a real database in production)
const posts: Post[] = [
  { id: 1, title: "Hello World", content: "This is the first post." },
  { id: 2, title: "Getting Started", content: "Welcome to the blog." },
];

export function getPosts(): Post[] {
  return posts;
}

export function createPost(title: string, content: string): Post {
  const post: Post = { id: posts.length + 1, title, content };
  posts.push(post);
  return post;
}

